const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], q = tok[1];
const B = 30;
const child = new Int32Array(2 * (n * B + 2)).fill(-1);      // child[2 * node + bit]
let nodes = 1;
for (let i = 0; i < n; i++) {
  const v = tok[2 + i];
  let node = 0;
  for (let b = B - 1; b >= 0; b--) {
    const bit = (v >> b) & 1;
    if (child[2 * node + bit] === -1) child[2 * node + bit] = nodes++;
    node = child[2 * node + bit];
  }
}
const out = [];
for (let j = 0; j < q; j++) {
  const x = tok[2 + n + j];
  let node = 0, best = 0;
  for (let b = B - 1; b >= 0; b--) {
    const bit = (x >> b) & 1;
    if (child[2 * node + (bit ^ 1)] !== -1) { best |= 1 << b; node = child[2 * node + (bit ^ 1)]; }
    else node = child[2 * node + bit];
  }
  out.push(best);
}
console.log(out.join('\n'));

