import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedInputStream(System.in));
        st.nextToken();
        int n = (int) st.nval;
        st.nextToken();
        int q = (int) st.nval;
        final int B = 30;
        int[] child = new int[2 * (n * B + 2)];
        Arrays.fill(child, -1);
        int nodes = 1;
        for (int i = 0; i < n; i++) {
            st.nextToken();
            int v = (int) st.nval;
            int node = 0;
            for (int b = B - 1; b >= 0; b--) {
                int bit = (v >> b) & 1;
                if (child[2 * node + bit] == -1) child[2 * node + bit] = nodes++;
                node = child[2 * node + bit];
            }
        }
        StringBuilder sb = new StringBuilder();
        for (int j = 0; j < q; j++) {
            st.nextToken();
            int x = (int) st.nval;
            int node = 0, best = 0;
            for (int b = B - 1; b >= 0; b--) {
                int bit = (x >> b) & 1;
                if (child[2 * node + (bit ^ 1)] != -1) { best |= 1 << b; node = child[2 * node + (bit ^ 1)]; }
                else node = child[2 * node + bit];
            }
            sb.append(best).append('\n');
        }
        System.out.print(sb);
    }
}

