#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, q;
    scanf("%d %d", &n, &q);
    const int B = 30;
    vector<array<int, 2>> trie(1, array<int, 2>{-1, -1});
    for (int i = 0; i < n; i++) {
        int v;
        scanf("%d", &v);
        int node = 0;
        for (int b = B - 1; b >= 0; b--) {
            int bit = (v >> b) & 1;
            if (trie[node][bit] == -1) {
                trie[node][bit] = trie.size();
                trie.push_back({-1, -1});
            }
            node = trie[node][bit];
        }
    }
    for (int j = 0; j < q; j++) {
        int x;
        scanf("%d", &x);
        int node = 0, best = 0;
        for (int b = B - 1; b >= 0; b--) {
            int bit = (x >> b) & 1;
            if (trie[node][bit ^ 1] != -1) { best |= 1 << b; node = trie[node][bit ^ 1]; }
            else node = trie[node][bit];
        }
        printf("%d\n", best);
    }
    return 0;
}
